questionvariables.text:
/* Design: which conditions a point satisfies. Entries [A, B, r, strict, side, points, categories]; strict 1: PA < r, 0: PA <= r; side 0 nearer A, 1 nearer B; categories 1 both, 2 condition 1 only, 3 condition 2 only, 4 neither. Each entry has a point on the circle and a point on the perpendicular bisector (found below); "both" is never first. Source: original. */
q72: [[[-2,-2],[4,-2],5,0,0,[[1,-3],[-6,-1],[2,-5],[-5,3]],[2,1,2,3]],[[-1,-2],[7,-2],5,1,0,[[3,1],[-6,-4],[3,-4],[1,-5]],[4,3,2,1]],[[-2,-1],[4,-1],5,0,1,[[1,-2],[2,-3],[1,-5],[3,-6]],[2,1,2,3]],[[-2,1],[4,1],5,1,1,[[-8,5],[2,1],[1,-1],[2,4]],[4,1,2,3]],[[-2,2],[6,2],5,0,0,[[2,0],[-7,7],[11,0],[-5,6]],[2,3,4,1]],[[-1,-2],[7,-2],5,1,0,[[9,0],[-5,-1],[3,-4],[-4,2]],[4,1,2,3]],[[-3,-2],[3,-2],5,0,1,[[-1,-8],[1,-5],[5,2],[0,-4]],[4,1,3,2]],[[-1,-1],[5,-1],5,1,1,[[2,-2],[5,2],[3,-3],[2,-5]],[2,3,1,4]],[[-2,-2],[4,-2],5,0,0,[[5,-7],[1,-6],[-4,-4],[1,-3]],[4,2,1,2]],[[-3,1],[5,1],5,1,0,[[2,1],[1,0],[-3,-5],[-1,2]],[4,2,3,1]]];
ix: 1+rand(10);
A: q72[ix][1]; B: q72[ix][2]; r: q72[ix][3]; st: q72[ix][4]; sd: q72[ix][5]; P: q72[ix][6]; cats: q72[ix][7];
pa2: makelist((P[k][1]-A[1])^2+(P[k][2]-A[2])^2, k, 1, 4);
pb2: makelist((P[k][1]-B[1])^2+(P[k][2]-B[2])^2, k, 1, 4);
keys: ["both","c1","c2","none"];
kyl: makelist(keys[cats[k]], k, 1, 4);
c1l: makelist(is(cats[k]<=2), k, 1, 4);
c2l: makelist(is(cats[k]=1 or cats[k]=3), k, 1, 4);
catf(u,w) := if u and w then 1 else if u then 2 else if w then 3 else 4;
/* row type: 1 on the circle (PA^2 = r^2), 2 on the perpendicular bisector (PA = PB), 3 plain */
ty: makelist(if is(pa2[k]=r^2) then 1 else if is(pa2[k]=pb2[k]) then 2 else 3, k, 1, 4);
/* diagnostic answer: condition 1 flipped (circle and plain rows), condition 2 flipped (bisector rows); generic: both flipped */
dg: makelist(if is(ty[k]=2) then keys[catf(c1l[k], not c2l[k])] else keys[catf(not c1l[k], c2l[k])], k, 1, 4);
gw: makelist(keys[catf(not c1l[k], not c2l[k])], k, 1, 4);
mko(c) := [["both",is(c=1),"both conditions"],["c1",is(c=2),"condition 1 only"],["c2",is(c=3),"condition 2 only"],["none",is(c=4),"neither condition"]];
o1: mko(cats[1]); o2: mko(cats[2]); o3: mko(cats[3]); o4: mko(cats[4]);
ta1: kyl[1]; ta2: kyl[2]; ta3: kyl[3]; ta4: kyl[4];
